<?php
namespace App\Controllers; use App\Middleware\Auth; use App\Services\Database; use App\Services\View; use App\Services\ATSAnalyzer;
final class ResumeController { public function index(){ Auth::requireUser(); $uid=Auth::user()['id']; $items=Database::pdo()->query("SELECT * FROM resumes WHERE user_id=$uid AND archived_at IS NULL ORDER BY updated_at DESC")->fetchAll(); View::render('resumes/index',['title'=>'My CVs','items'=>$items]); } public function create(){ Auth::requireUser(); $db=Database::pdo(); $st=$db->prepare('INSERT INTO resumes(user_id,name,template_key,content_json,section_order,public_token,created_at,updated_at) VALUES(?,?,?,?,?,?,NOW(),NOW())'); $content=['personal'=>['full_name'=>Auth::user()['name'],'email'=>Auth::user()['email']],'summary'=>'','experience'=>[],'education'=>[],'skills'=>[],'projects'=>[]]; $st->execute([Auth::user()['id'],'Untitled CV','modern',json_encode($content),json_encode(['summary','experience','skills','education','projects','certifications']),bin2hex(random_bytes(16))]); \redirect('/resumes/'.$db->lastInsertId().'/edit'); } public function edit($id){ Auth::requireUser(); $r=$this->find($id); View::render('resumes/builder',['title'=>'CV Builder','resume'=>$r]); } public function save($id){ Auth::requireUser(); \verify_csrf(); $this->find($id); $content=json_decode($_POST['content_json']??'{}',true) ?: []; $st=Database::pdo()->prepare('UPDATE resumes SET name=?,template_key=?,content_json=?,section_order=?,updated_at=NOW() WHERE id=? AND user_id=?'); $st->execute([$_POST['name']??'Untitled CV',$_POST['template_key']??'modern',json_encode($content),$_POST['section_order']??'[]',$id,Auth::user()['id']]); \json_response(['success'=>true,'message'=>'CV saved successfully']); } public function scan($id){ Auth::requireUser(); $r=$this->find($id); $data=json_decode($r['content_json'],true) ?: []; \json_response(['success'=>true,'data'=>(new ATSAnalyzer)->scan($data,$_POST['job_description']??'')]); } public function public($token){ $db=Database::pdo(); $st=$db->prepare('SELECT * FROM resumes WHERE public_token=? AND public_enabled=1'); $st->execute([$token]); $r=$st->fetch(); if(!$r){http_response_code(404); exit('Not found');} View::render('resumes/public',['title'=>$r['name'],'resume'=>$r]); } private function find($id){ $st=Database::pdo()->prepare('SELECT * FROM resumes WHERE id=? AND user_id=?'); $st->execute([$id,Auth::user()['id']]); return $st->fetch() ?: (http_response_code(404) && exit('Not found')); }}
